import re,json,urllib.request,concurrent.futures
seen=set(); keys=[]
for f in ["nomask_live_keys.txt","nm2_api.txt","nm_api_keys.txt","nm_ready.txt"]:
    try:
        for l in open(f):
            m=re.search(r"(nmk_live_[A-Za-z0-9]+)",l)
            if m and m.group(1) not in seen:
                seen.add(m.group(1)); keys.append((m.group(1), l.split("|")[0].strip()))
    except FileNotFoundError: pass
print("total key unik:",len(keys))
def test(item):
    k,e=item
    body=json.dumps({"model":"glm-5.3_flash_uncensored","messages":[{"role":"user","content":"hi"}],"max_tokens":5}).encode()
    r=urllib.request.Request("https://api.nomask.ai/v1/chat/completions",data=body,
        headers={"Authorization":f"Bearer {k}","Content-Type":"application/json"})
    try:
        with urllib.request.urlopen(r,timeout=60) as x: return (k,e,"LIVE")
    except urllib.error.HTTPError as ex:
        t=ex.read().decode()[:120]
        if "balance" in t: return (k,e,"EMPTY")
        if ex.code==429: return (k,e,"RATE")
        return (k,e,f"HTTP{ex.code}")
    except Exception as ex: return (k,e,"ERR")
res=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    for x in ex.map(test,keys): res.append(x)
